def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(x for row in grid for x in row),
             key=lambda x: sum(row.count(x) for row in grid))

    # Marker color is the most frequent color appearing as isolated pixels.
    isolated = {}
    counts = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v == bg:
                continue
            counts[v] = counts.get(v, 0) + 1
            if all(not (0 <= r+dr < h and 0 <= c+dc < w and
                        grid[r+dr][c+dc] == v)
                   for dr, dc in ((1,0),(-1,0),(0,1),(0,-1))):
                isolated[v] = isolated.get(v, 0) + 1
    marker = max(isolated, key=lambda x: (isolated[x], counts.get(x, 0)))

    # Find the longest straight run belonging to the source pattern.
    best = None
    for dr, dc in ((0, 1), (1, 0)):
        for r in range(h):
            for c in range(w):
                pr, pc = r-dr, c-dc
                if 0 <= pr < h and 0 <= pc < w and grid[pr][pc] not in (bg, marker):
                    continue
                run = []
                rr, cc = r, c
                while (0 <= rr < h and 0 <= cc < w and
                       grid[rr][cc] not in (bg, marker)):
                    run.append((rr, cc))
                    rr += dr
                    cc += dc
                if len(run) >= 3 and (best is None or len(run) > len(best[0])):
                    best = (run, dr, dc)

    if best is None:
        return [row[:] for row in grid]

    run, dr, dc = best
    # The pattern is centered on its middle cell; an even visible run
    # may have a background-colored endpoint.
    if len(run) % 2 == 0:
        rr, cc = run[-1][0] + dr, run[-1][1] + dc
        if 0 <= rr < h and 0 <= cc < w:
            run.append((rr, cc))

    pattern = [grid[r][c] for r, c in run]
    anchor = len(pattern) // 2
    out = [row[:] for row in grid]

    for r in range(h):
        for c in range(w):
            if grid[r][c] == marker:
                for i, value in enumerate(pattern):
                    rr = r + (i-anchor)*dr
                    cc = c + (i-anchor)*dc
                    if 0 <= rr < h and 0 <= cc < w:
                        out[rr][cc] = value
    return out
